"""OpenTrip bookings family for the Windows platform.

Every OpenTrip instruction on this platform ends with the same observable
outcome: a set of confirmed bookings held in the application's own store, under
a signed-in session.  This base reads that store through the application's
read-only local API and decides the task from the booking records themselves --
the identifier, the booked item, the traveller, the cabin, the payment method
and the note.  How the agent reached the checkout page, how many steps it took
and in which order are not part of the decision.

State is read from the guest over the runtime; when the store cannot be reached
the session and the bookings are simply absent, which is the starting state of
an unperformed task.
"""

from __future__ import annotations

import json
from typing import Any, Mapping

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus

DEFAULT_PORT = 4330
STATE_ERROR = "OpenTrip store could not be read"

#: The store's read-only documents.  The session and the bookings are separate
#: documents and both are needed: the bookings document is only served to a
#: signed-in session, so an unperformed task answers it with 401.
SESSION_PATH = "/api/session"
BOOKINGS_PATH = "/api/bookings"


class _HttpProbe:
    """Read one JSON document from the application's local API inside the guest."""

    def __init__(self, controller: Any, port: int, timeout: int = 15) -> None:
        self.controller = controller
        self.port = int(port)
        self.timeout = int(timeout)

    def get(self, path: str) -> Any:
        """Read one document, or ``None`` when the store does not serve it.

        A document the store withholds because no session is signed in, or does
        not answer at all, is simply absent: that is the starting state of an
        unperformed task rather than an evaluator fault.
        """
        script = (
            "import json, urllib.error, urllib.request\n"
            "try:\n"
            f"    with urllib.request.urlopen('http://127.0.0.1:{self.port}{path}',"
            f" timeout={self.timeout}) as response:\n"
            "        print(response.read().decode('utf-8'))\n"
            "except urllib.error.HTTPError as exc:\n"
            "    print(json.dumps({'withheld': exc.code}))\n"
            "except Exception as exc:\n"
            "    print(json.dumps({'withheld': type(exc).__name__}))\n"
        )
        result = self.controller.run_python_script(script, timeout=self.timeout + 5)
        stdout = str(result.get("stdout") or result.get("output") or "").strip()
        if int(result.get("returncode", -1)) != 0 and not stdout:
            return None
        try:
            payload = json.loads(stdout)
        except (TypeError, ValueError):
            return None
        if isinstance(payload, Mapping) and "withheld" in payload:
            return None
        return payload


class OpenTripBookingEvaluator(BaseEvaluator):
    """Decide an OpenTrip task from the bookings held in the application store."""

    TASK_PARAMS: dict[str, Any] = {"port": DEFAULT_PORT, "timeout": 15}

    # -- state ---------------------------------------------------------
    @classmethod
    def read_state(cls, controller: Any, params: Mapping[str, Any]) -> dict[str, Any]:
        """Read the session and the bookings the application holds."""
        probe = _HttpProbe(controller, int(params.get("port", DEFAULT_PORT)),
                           int(params.get("timeout", 15)))
        session = probe.get(SESSION_PATH)
        bookings = probe.get(BOOKINGS_PATH)
        state: dict[str, Any] = {}
        if isinstance(session, Mapping):
            state["session"] = session.get("session")
        if isinstance(bookings, Mapping):
            state["bookings"] = bookings
            if "session" in bookings and "session" not in state:
                state["session"] = bookings["session"]
        return state

    # -- comparison helpers --------------------------------------------
    @staticmethod
    def _bookings(state: Mapping[str, Any]) -> list[dict[str, Any]]:
        rows = state.get("bookings")
        if isinstance(rows, Mapping):
            rows = rows.get("bookings")
        if not isinstance(rows, list):
            return []
        return [dict(row) for row in rows if isinstance(row, Mapping)]

    @staticmethod
    def _value(booking: Mapping[str, Any], key: str) -> Any:
        """Read one flat field, looking through the booking's nested records."""
        if key in booking:
            return booking.get(key)
        # The desktop API stores camelCase fields and nested objects; the task
        # contract uses explicit snake_case names. Never use booking.id for
        # item_id, nor item.name for traveler_name/room_name.
        paths = {
            "item_id": ("item", "id"),
            "flight_no": ("item", "flightNo"),
            "flight_from": ("item", "from"),
            "flight_to": ("item", "to"),
            "flight_date": ("item", "date"),
            "hotel_name": ("item", "name"),
            "room_id": ("room", "id"),
            "room_name": ("room", "name"),
            "traveler_id": ("traveler", "id"),
            "traveler_name": ("traveler", "name"),
            "traveler_document_type": ("traveler", "documentType"),
            "check_in": ("checkIn",),
            "check_out": ("checkOut",),
            "contact_phone": ("contactPhone",),
        }
        if key in paths:
            value: Any = booking
            for part in paths[key]:
                if not isinstance(value, Mapping):
                    return None
                value = value.get(part)
            return value
        for section in ("item", "traveler", "room", "payment", "charges"):
            nested = booking.get(section)
            if isinstance(nested, Mapping) and key in nested:
                return nested.get(key)
        return None

    @classmethod
    def _matches(cls, booking: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
        """True when ``booking`` carries every expected field at its exact value."""
        for key, want in expected.items():
            if key in ("label", "id_prefix", "payment_label"):
                continue
            got = cls._value(booking, key)
            if key in ("type", "status", "cabin", "note", "contact_phone"):
                if str(got) != str(want):
                    return False
            elif key == "guests":
                if int(got or -1) != int(want):
                    return False
            elif key == "payment_id":
                payment = booking.get("payment")
                if not isinstance(payment, Mapping) or str(payment.get("id")) != str(want):
                    return False
            else:
                if str(got) != str(want):
                    return False
        prefix = expected.get("id_prefix")
        if prefix and not str(booking.get("id") or "").startswith(str(prefix)):
            return False
        label = expected.get("payment_label")
        if label:
            payment = booking.get("payment")
            if not isinstance(payment, Mapping) or str(payment.get("label")) != str(label):
                return False
        return True

    # -- judging -------------------------------------------------------
    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = self._context_params(context)
        controller = context.get("controller")
        expected = list(params.get("required_bookings") or [])
        session_spec = dict(params.get("session") or {})

        try:
            state = self.read_state(controller, params)
        except Exception:  # noqa: BLE001 - an unreadable store is an unperformed task
            state = {}

        checks: list[dict[str, Any]] = []
        bookings = self._bookings(state)
        session = state.get("session")
        session = dict(session) if isinstance(session, Mapping) else {}

        if session_spec:
            want_login = bool(session_spec.get("logged_in", True))
            logged_in = bool(session.get("loggedIn"))
            user = session.get("user")
            user = dict(user) if isinstance(user, Mapping) else {}
            session_ok = logged_in == want_login
            for key, field in (("phone", "phone"), ("name", "name")):
                if want_login and session_spec.get(key) is not None:
                    session_ok = session_ok and str(user.get(field) or "") == str(session_spec[key])
            checks.append({
                "check_id": "session",
                "passed": session_ok,
                "expected": session_spec,
                "observed": {"loggedIn": session.get("loggedIn"), "user": user},
                "failure_reason": "" if session_ok else "the session is not the one the task requires",
            })

        for spec in expected:
            label = str(spec.get("label") or spec.get("item_id") or "booking")
            matched = [row for row in bookings if self._matches(row, spec)]
            passed = len(matched) == 1
            checks.append({
                "check_id": f"booking.{label}",
                "passed": passed,
                "expected": spec,
                "observed": {
                    "match_count": len(matched),
                    "candidates": [
                        {"id": row.get("id"), "type": row.get("type"),
                         "status": row.get("status"), "note": row.get("note")}
                        for row in bookings
                    ],
                },
                "failure_reason": "" if passed else f"booking {label} is not held exactly once",
            })

        extra = params.get("forbidden_extra_bookings")
        if extra is not None:
            total = len(bookings)
            passed = total == len(expected)
            checks.append({
                "check_id": "booking_count",
                "passed": passed,
                "expected": len(expected),
                "observed": total,
                "failure_reason": "" if passed else "the store holds a different number of bookings",
            })

        failed = [row["check_id"] for row in checks if not row["passed"]]
        metadata = {
            "read_only": True,
            "bookings": bookings,
            "checks": checks,
            "failed_checks": failed,
            "state_readable": bool(state),
        }
        if not checks:
            return EvalResult(status=EvalStatus.ERROR, message="no booking criteria declared",
                              metadata=metadata)
        if failed:
            return EvalResult(status=EvalStatus.FAIL,
                              message="OpenTrip booking evaluation failed: " + ", ".join(failed),
                              metadata=metadata)
        return EvalResult(status=EvalStatus.PASS, message="OpenTrip booking evaluation passed",
                          metadata=metadata)


